result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "auditlog.py", "content": """"Hash-chained audit log with size-based segment rotation.

Records are JSON lines of the form:

    {"seq": <int>, "prev": <hex>, "event": {...}, "h": <hex>}

where ``h = sha256("{seq}|{sorted-canonical-json(event)}|{prev}")``.

When a segment file ``audit-<k>.log`` reaches ``max_records`` records it is
closed and a new segment begins whose first record's ``prev`` is the LAST
hash of the previous segment (chain crosses segment boundaries). A
``manifest.json`` tracks segment order, record counts and final hashes.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
from dataclasses import dataclass, field

_GENESIS = "0" * 64
_SEG_RE = re.compile(r"^audit-(\d+)\.log$")
MANIFEST_NAME = "manifest.json"


def _canonical(event: dict) -> str:
    return json.dumps(event, sort_keys=True, separators=(",", ":"))


def _record_hash(seq: int, event: dict, prev: str) -> str:
    payload = f"{seq}|{_canonical(event)}|{prev}"
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


class AuditWriter:
    """Appends hash-chained events to rotating segment files."""

    def __init__(self, directory, max_records: int = 100):
        if max_records < 1:
            raise ValueError("max_records must be >= 1")
        self.dir = os.fspath(directory)
        self.max_records = max_records
        os.makedirs(self.dir, exist_ok=True)

        # Each entry: {"file", "records", "first_hash", "last_hash"}
        self.segments: list[dict] = []
        self.next_seq = 1
        self._fh = None
        self._scan_existing()
        self._open_current()

    # ------------------------------------------------------------------ setup

    def _seg_files(self):
        found = []
        for name in os.listdir(self.dir):
            m = _SEG_RE.match(name)
            if m:
                found.append((int(m.group(1)), name))
        found.sort()
        return [name for _, name in found]

    def _scan_existing(self):
        """Recover chain state from any existing segments on disk."""
        last_seq = 0
        for name in self._seg_files():
            records = 0
            first_hash = None
            last_hash = _GENESIS
            with open(os.path.join(self.dir, name), "r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    rec = json.loads(line)
                    if records == 0:
                        first_hash = rec["h"]
                    last_hash = rec["h"]
                    last_seq = rec["seq"]
                    records += 1
            self.segments.append(
                {
                    "file": name,
                    "records": records,
                    "first_hash": first_hash,
                    "last_hash": last_hash,
                }
            )
        if not self.segments:
            self.segments.append(
                {
                    "file": "audit-0.log",
                    "records": 0,
                    "first_hash": None,
                    "last_hash": _GENESIS,
                }
            )
        self.next_seq = last_seq + 1

    def _open_current(self):
        cur = self.segments[-1]
        if cur["records"] >= self.max_records:
            self._rotate()
            return
        self._fh = open(os.path.join(self.dir, cur["file"]), "a", encoding="utf-8")

    def _rotate(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        prev_last = self.segments[-1]["last_hash"]
        self.segments.append(
            {
                "file": f"audit-{len(self.segments)}.log",
                "records": 0,
                "first_hash": None,
                "last_hash": prev_last,
            }
        )
        self._fh = open(
            os.path.join(self.dir, self.segments[-1]["file"]), "a", encoding="utf-8"
        )

    # ----------------------------------------------------------------- append

    def append(self, event: dict) -> str:
        cur = self.segments[-1]
        if cur["records"] >= self.max_records:
            self._rotate()
            cur = self.segments[-1]

        seq = self.next_seq
        prev = cur["last_hash"]
        h = _record_hash(seq, event, prev)
        record = {"seq": seq, "prev": prev, "event": event, "h": h}
        self._fh.write(json.dumps(record, separators=(",", ":")) + "\n")

        if cur["records"] == 0:
            cur["first_hash"] = h
        cur["records"] += 1
        cur["last_hash"] = h
        self.next_seq = seq + 1

        self._fh.flush()
        self._write_manifest()
        return h

    # --------------------------------------------------------------- manifest

    def _write_manifest(self):
        manifest = {
            "max_records": self.max_records,
            "segments": [
                {
                    "file": s["file"],
                    "records": s["records"],
                    "first_hash": s["first_hash"],
                    "last_hash": s["last_hash"],
                }
                for s in self.segments
            ],
        }
        tmp = os.path.join(self.dir, MANIFEST_NAME + ".tmp")
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(manifest, fh, indent=2)
        os.replace(tmp, os.path.join(self.dir, MANIFEST_NAME))

    # ------------------------------------------------------------------ close

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        self._write_manifest()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()


# ------------------------------------------------------------------ verifier


@dataclass
class VerifyResult:
    errors: list[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.errors


def verify_all(directory) -> VerifyResult:
    """Validate every segment, cross-segment linkage, and the manifest."""
    d = os.fspath(directory)
    errors: list[str] = []

    files = []
    for name in os.listdir(d):
        m = _SEG_RE.match(name)
        if m:
            files.append((int(m.group(1)), name))
    files.sort()
    files = [name for _, name in files]

    # ---- manifest consistency -------------------------------------------
    manifest = None
    mpath = os.path.join(d, MANIFEST_NAME)
    if os.path.exists(mpath):
        try:
            with open(mpath, "r", encoding="utf-8") as fh:
                manifest = json.load(fh)
        except (OSError, json.JSONDecodeError) as exc:
            errors.append(f"manifest.json: unreadable ({exc})")

    manifest_stats = {}
    if isinstance(manifest, dict):
        mfiles = [e.get("file") for e in manifest.get("segments", [])]
        on_disk, listed = set(files), set(mfiles)

        for name in mfiles:
            if name not in on_disk:
                errors.append(
                    f"manifest.json: missing segment {name} "
                    f"(manifest declares {len(mfiles)} segment(s), "
                    f"found {len(files)} on disk)"
                )
        for name in files:
            if name not in listed:
                errors.append(f"manifest.json: unexpected segment {name} not listed")
        if on_disk == listed and mfiles != files:
            errors.append(
                f"manifest.json: segment order mismatch: manifest={mfiles}, disk={files}"
            )

        manifest_stats = {
            e.get("file"): e
            for e in manifest.get("segments", [])
            if isinstance(e, dict)
        }

    # ---- chain verification (single pass over all segments in order) -----
    expected_seq = 1
    expected_prev = _GENESIS
    stats = {}  # file -> {"records", "first_hash", "last_hash"}

    for name in files:
        records = 0
        first_hash = None
        last_hash = None
        with open(os.path.join(d, name), "r", encoding="utf-8") as fh:
            for lineno, line in enumerate(fh, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                except json.JSONDecodeError as exc:
                    errors.append(f"{name}: line {lineno} invalid JSON ({exc})")
                    break

                seq = rec.get("seq")
                ev = rec.get("event")
                prev = rec.get("prev")
                h = rec.get("h")

                if seq != expected_seq:
                    errors.append(
                        f"{name}: seq={seq} out of order (expected {expected_seq})"
                    )
                if prev != expected_prev:
                    errors.append(
                        f"{name}: seq={seq} broken prev link "
                        f"(got {str(prev)[:12]}..., expected {str(expected_prev)[:12]}...)"
                    )
                computed = _record_hash(seq, ev, prev)
                if h != computed:
                    errors.append(
                        f"{name}: seq={seq} hash mismatch (record tampered)"
                    )

                if records == 0:
                    first_hash = h
                last_hash = h
                records += 1
                expected_prev = computed
                expected_seq = seq + 1

        stats[name] = {
            "records": records,
            "first_hash": first_hash,
            "last_hash": last_hash,
        }

    # ---- manifest per-segment stats --------------------------------------
    for name, entry in manifest_stats.items():
        actual = stats.get(name)
        if actual is None:
            continue
        if entry.get("records") != actual["records"]:
            errors.append(
                f"manifest.json: {name} record count {entry.get('records')} "
                f"!= actual {actual['records']}"
            )
        if entry.get("last_hash") != actual["last_hash"]:
            errors.append(
                f"manifest.json: {name} final hash mismatch with file contents"
            )

    return VerifyResult(errors=errors)
"})
